36	@@ -0,0 +1,36 @@
37	+"""PlatformIO pre-build script: converts xscreensaver's pacman.png into the
38	+raw blob pacman.c includes as images/gen/pacman_png.h (see
39	+src/x11shim/include/ximage-loader.h for the format) and puts it on the include
40	+path. The image is read from vendor/ and never committed; its header is
41	+3 MB of C text. Needs uv, because Pillow is not in PlatformIO's Python."""
42	+
43	+import shutil
44	+import subprocess
45	+import sys
46	+from pathlib import Path
47	+
48	+Import("env")  # noqa: F821
49	+
50	+repo = Path(env["PROJECT_DIR"]).parent  # noqa: F821
51	+image = repo / "vendor" / "xscreensaver-6.16" / "hacks" / "images" / "pacman.png"
52	+converter = repo / "tools" / "make_logo_blob.py"
53	+generated = Path(env.subst("$BUILD_DIR")) / "generated"  # noqa: F821
54	+header = generated / "images" / "gen" / "pacman_png.h"
55	+
56	+if not image.is_file():
57	+    sys.exit(f"{image} is missing: run `uv run tools/fetch_xscreensaver.py`")
58	+if (
59	+    not header.exists()
60	+    or header.stat().st_mtime < image.stat().st_mtime
61	+    or header.stat().st_mtime < converter.stat().st_mtime
62	+):
63	+    uv = shutil.which("uv")
64	+    if not uv:
65	+        sys.exit("pacman_sprites.py needs uv on PATH to convert pacman.png")
66	+    header.parent.mkdir(parents=True, exist_ok=True)
67	+    subprocess.run(
68	+        [uv, "run", str(converter), str(image), "--name", "pacman_png", "-o", str(header)],
69	+        check=True,
70	+    )
71	+
72	+env.Append(CPPPATH=[str(generated)])  # noqa: F821
