+static void track(Display *dpy, struct XshimPixmap *pm) {
+  pm->prev = NULL;
+  pm->next = dpy->pixmaps;
+  if (dpy->pixmaps) dpy->pixmaps->prev = pm;
+  dpy->pixmaps = pm;
