+  unsigned char *stack = (unsigned char *)mem;
+  memset(stack, STACK_PAINT, STACK_PROBE_BYTES);
+  pthread_attr_t attr;
+  pthread_attr_init(&attr);
+  if (pthread_attr_setstack(&attr, stack, STACK_PROBE_BYTES) != 0) return -2;
+  probe_hack = hack;
+  probe_seed = seed;
+  probe_frames = frames;

