759	+"""Patches that keep Pacman inside the board's 16 KB loop-task stack.
760	+
761	+1. patch_pacman_level: always use the fixed level (below).
762	+2. patch_pacman_ai: turn the ghosts' recursive route search into a loop (end of
763	+   this file).
764	+
765	+Make pacman_level.c always use its fixed level.
766	+
767	+`pacman_createnewlevel` builds half its levels with a random generator
768	+(`creatlevelblock` and `nextstep`) and copies the fixed `stdlevel` for the
769	+rest. The generator calls itself once per tile and keeps a 1.3 KB copy of the
770	+level in every frame, so a level takes up to about 300 KB of stack. The board's
771	+loop task has 16 KB, and Pacman reboots the board on its first frame when the
772	+generator runs.
773	+
774	+The copied pacman_level.c stays byte-identical to upstream. The firmware build
775	+writes a patched copy with `firmware/patch_pacman.py` and compiles that
776	+instead. The generator is still compiled but never called.
777	+"""
778	+
779	+import hashlib
780	+
781	+RANDOM_LEVEL_TEST = "if (NRAND (2) == 0) {"
782	+FIXED_LEVEL_COPY = "memcpy (level, stdlevel, sizeof (lev_t))"
783	+REPLACEMENT = "if (0) { /* patched: the random generator needs ~300 KB of stack */"
784	+
785	+
786	+def patch_pacman_level(source: str) -> str:
787	+    found = source.count(RANDOM_LEVEL_TEST)
788	+    if found != 1:
789	+        raise ValueError(
790	+            f"expected one `{RANDOM_LEVEL_TEST}` (the NRAND choice in "
791	+            f"pacman_createnewlevel), found {found}; has upstream changed?"
792	+        )
793	+    if FIXED_LEVEL_COPY not in source:
794	+        raise ValueError(
795	+            f"`{FIXED_LEVEL_COPY}` (the stdlevel branch) is gone; has upstream changed?"
796	+        )
797	+    return source.replace(RANDOM_LEVEL_TEST, REPLACEMENT)
798	+
799	+
800	+BACK_TRACK_START = "static int\nrecur_back_track ("
801	+BACK_TRACK_END = "static void\nfind_home"
802	+BACK_TRACK_SHA256 = "5a15acb09a9f8b768b65d3630f9a1eb35956c0627830a6f49d0f0de78939dfbc"
803	+
804	+# A depth-first search that visits the cells in the same order as upstream's
805	+# recursion (left, up, down, right), saves positions and stores directions in
806	+# the same order, but keeps its frames in a heap array. The recursion reached
807	+# 453 levels of 48 bytes from some cells (about 22 KB, against a 16 KB loop
808	+# stack); a path cannot be deeper than the ghost's trace, GHOST_TRACE cells.
809	+NEW_BACK_TRACK = """typedef struct {
810	+    int row, col, next;
811	+} bt_frame;
812	+
813	+static const pos bt_order[4] = { pos_left, pos_up, pos_down, pos_right };
814	+
815	+/* Enters the cell (row, col) as recur_back_track did on a call: returns False
816	+ * or True if the call would return at once, and -1 after pushing a frame. */
817	+static int
818	+bt_enter ( ghoststruct *g, bt_frame *stack, int *top, int row, int col ){
819	+    if ( already_tried ( g, col, row ) )
820	+        return False;
821	+
822	+    if ( found_jail ( col, row ) )
823	+        return True;
824	+
825	+    save_position ( g, col, row );
826	+    (*top)++;
827	+    stack[*top].row = row;
828	+    stack[*top].col = col;
829	+    stack[*top].next = 0;
830	+    return -1;
831	+}
832	+
833	+/* Patched: the recursion is a loop over a heap stack, in the same order. */
834	+static int
835	+recur_back_track ( pacmangamestruct * pp, ghoststruct *g, int row, int col ){
836	+    bt_frame *stack = (bt_frame *) malloc ( sizeof ( bt_frame ) * GHOST_TRACE );
837	+    int top = -1, ret;
838	+
839	+    if ( stack == NULL )
840	+        return False;
841	+
842	+    ret = bt_enter ( g, stack, &top, row, col );
843	+    while ( top >= 0 ){
844	+        bt_frame *f = &stack[top];
845	+        int descended = False;
846	+
847	+        if ( ret == True ){
848	+            /* the call just made returned True: this frame stores its move */
849	+            store_dir ( g, bt_order[f->next - 1] );
850	+            top--;
851	+            continue;
852	+        }
853	+
854	+        while ( f->next < 4 ){
855	+            int new_row, new_col;
856	+            pos d = bt_order[f->next++];
857	+
858	+            if ( move_ghost ( pp, f->row, f->col, d, &new_row, &new_col )){
859	+                ret = bt_enter ( g, stack, &top, new_row, new_col );
860	+                descended = True;
861	+                break;
862	+            }
863	+        }
864	+        if ( !descended ){
865	+            top--;
866	+            ret = False;
867	+        }
868	+    }
869	+    free ( stack );
870	+    return ret;
871	+}
872	+
873	+"""
874	+
875	+
876	+def patch_pacman_ai(source: str) -> str:
877	+    found = source.count(BACK_TRACK_START)
878	+    if found != 1:
879	+        raise ValueError(
880	+            f"expected one `recur_back_track` definition, found {found}; "
881	+            "has upstream pacman_ai.c changed?"
882	+        )
883	+    start = source.index(BACK_TRACK_START)
884	+    end = source.find(BACK_TRACK_END, start)
885	+    if end < 0:
886	+        raise ValueError("find_home no longer follows recur_back_track; has upstream changed?")
887	+    original = source[start:end]
888	+    if hashlib.sha256(original.encode()).hexdigest() != BACK_TRACK_SHA256:
889	+        raise ValueError(
890	+            "recur_back_track has changed upstream; check the rewrite still "
891	+            "visits cells and stores directions in the same order"
892	+        )
893	+    return source[:start] + NEW_BACK_TRACK + source[end:]
